<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require_login();$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$md=$month.'-01';$error=$notice='';$rows=[];$edit=null;try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$code=trim((string)($_POST['model_code']??''));$name=trim((string)($_POST['model_name']??''));$qty=max(0,(int)($_POST['planned_qty']??0));if(!$code)throw new RuntimeException('Model code is required.');if($id){db()->prepare('UPDATE dbo.web_monthly_plan SET model_code=?,model_name=?,planned_qty=?,updated_by=?,updated_at=SYSDATETIME() WHERE id=?')->execute([$code,$name,$qty,current_user()['username'],$id]);audit_log('UPDATE','monthly_plan',$id,'Updated monthly target '.$code);}else{db()->prepare('INSERT INTO dbo.web_monthly_plan(plan_month,model_code,model_name,planned_qty,created_by) VALUES(?,?,?,?,?)')->execute([$md,$code,$name,$qty,current_user()['username']]);audit_log('CREATE','monthly_plan',null,'Created monthly target '.$code);}$notice='Monthly target saved.';}elseif($a==='delete'){$id=(int)$_POST['id'];db()->prepare('DELETE FROM dbo.web_monthly_plan WHERE id=?')->execute([$id]);audit_log('DELETE','monthly_plan',$id,'Deleted monthly target');$notice='Target deleted.';}}$s=db()->prepare('SELECT * FROM dbo.web_monthly_plan WHERE plan_month=? ORDER BY model_code');$s->execute([$md]);$rows=$s->fetchAll();if(isset($_GET['edit']))foreach($rows as $r)if((int)$r['id']===(int)$_GET['edit'])$edit=$r;}catch(Throwable $e){$error=$e->getMessage();}$e=$edit??[];?><?php $pageTitle='Monthly Schedule'; $activePage='monthly'; require __DIR__.'/includes/header.php'; ?><section class="content"><div class="page-intro"><div><h2>Monthly production targets</h2><p>One target per model per month. Legacy TB_MONTHLY is preserved.</p></div><form><input type="month" name="month" value="<?=h($month)?>" onchange="this.form.submit()"></form></div><?php if($notice):?><div class="notice notice-success"><?=h($notice)?></div><?php endif;?><?php if($error):?><div class="notice notice-error"><?=h($error)?></div><?php endif;?><section class="panel"><div class="panel-head"><h3><?= $edit?'Edit target':'Add target'?></h3></div><form method="post" style="display:grid;grid-template-columns:2fr 2fr 1fr auto;gap:12px;padding:18px;align-items:end"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($e['id']??'')?>"><label class="field"><span>Model / Part No.</span><input name="model_code" required value="<?=h($e['model_code']??'')?>"></label><label class="field"><span>Model Name</span><input name="model_name" value="<?=h($e['model_name']??'')?>"></label><label class="field"><span>Planned Qty</span><input type="number" min="0" name="planned_qty" value="<?=h($e['planned_qty']??0)?>"></label><button class="btn btn-primary">Save</button></form></section><section class="panel data-panel"><div class="panel-head"><h3><?=h(date('F Y',strtotime($md)))?> targets</h3><span class="record-count"><?=count($rows)?> models · Total <?=number_format(array_sum(array_map(fn($r)=>(int)$r['planned_qty'],$rows)))?></span></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Model Code</th><th>Model Name</th><th>Planned Qty</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['model_code'])?></td><td><?=h($r['model_name'])?></td><td><?=number_format((int)$r['planned_qty'])?></td><td><a class="btn btn-secondary btn-small" href="?month=<?=h($month)?>&edit=<?=(int)$r['id']?>">Edit</a><form method="post" style="display:inline" onsubmit="return confirm('Delete target?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-ghost btn-small">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">No monthly targets yet.</td></tr><?php endif;?></tbody></table></div></section></section><?php require __DIR__.'/includes/footer.php'; ?>